/**
 * This library manage the communication between dashlet and web client.
 */
const msgQueue = {};
const alertQueue = [];

let modalDialog = false;

let webclientOrigin;
let trustedOrigin;

let onInitCallback = () => {};
let onUpdateCallback = () => {};
let onUpdateCallbackRegistered = false;
let onObjectCreationCallback;

/**
 * Caps the outcomes buffered before the dashlet registers its callback. The webclient keeps only one createNew call
 * open at a time, so the cap only matters for a dashlet that never registers.
 */
const MAX_PENDING_OBJECT_CREATION_EVENTS = 20;
// objectCreation events which arrived before a callback was registered, oldest first.
const pendingObjectCreationEvents = [];
let objectCreationFlushTimer;

/**
 * Registers an onInit callback which is executed once the dashlet is initialized.
 *
 * @param {Function} callback
 * @param {string} allowedOrigin origin which is allowed to send and receive messages. Should be the webclient uri.
 * Use "*" to allow every target origin. Example: https://enaio.company-name.de.
 * Ref: https://developer.mozilla.org/en-US/docs/Web/API/Window/postMessage
 */
function registerOnInitCallback(callback, allowedOrigin) {
    onInitCallback = callback;
    trustedOrigin = allowedOrigin;
}

/**
 * Registers an onUpdate callback which is executed if something changes in the client.
 *
 * @param {Function} callback The callback
 * @param {string} allowedOrigin origin which is allowed to send and receive messages. Should be the webclient uri.
 * Use "*" to allow every target origin. Example: https://enaio.company-name.de.
 * Ref: https://developer.mozilla.org/en-US/docs/Web/API/Window/postMessage
 */
function registerOnUpdateCallback(callback, allowedOrigin) {
	if (modalDialog) {
		throw "Modal dialogs do not trigger a update event. Please do not register one.";
	} else {
		onUpdateCallbackRegistered = true;
		onUpdateCallback = callback;
		trustedOrigin = allowedOrigin;
	}
}

/**
 * Registers a callback which receives the outcome of an object creation started with createNew.
 * Events which arrived before the registration (at most the last 20) are delivered to the callback
 * afterwards in their order of arrival, on a new task and not inside this call.
 *
 * @param {Function} callback The callback
 */
function registerOnObjectCreationCallback(callback) {
    onObjectCreationCallback = callback;

    if (pendingObjectCreationEvents.length > 0 && objectCreationFlushTimer === undefined) {
        objectCreationFlushTimer = setTimeout(flushPendingObjectCreationEvents, 0);
    }
}

/**
 * Delivers the buffered objectCreation events to the registered callback in their order of arrival.
 * Events from an origin which is not trusted (any more) are dropped.
 */
function flushPendingObjectCreationEvents() {
    objectCreationFlushTimer = undefined;

    for (const {origin, data} of pendingObjectCreationEvents.splice(0)) {
        if (!isTrustedOrigin(origin)) {
            console.log(`objectCreation event from ${origin} dropped, it is different from srcOrigin ${trustedOrigin}`);
            continue;
        }

        deliverObjectCreationEvent(data);
    }
}

/**
 * Hands an objectCreation event to the registered callback. An error of the callback is thrown again on a new task,
 * so that the remaining events are still delivered.
 *
 * @param data The outcome of the object creation.
 */
function deliverObjectCreationEvent(data) {
    try {
        onObjectCreationCallback(data);
    } catch (error) {
        setTimeout(() => {
            throw error;
        }, 0);
    }
}

/**
 * Hands an objectCreation event to the registered callback. Without a callback, or while buffered events
 * are still waiting for their delivery, the event is buffered so that the order of arrival is kept.
 * The origin is kept with it, because a trusted origin may only be set after the event arrived.
 *
 * @param data The outcome of the object creation.
 * @param origin The origin the event came from.
 */
function handleObjectCreationEvent(data, origin) {
    if (onObjectCreationCallback && objectCreationFlushTimer === undefined) {
        deliverObjectCreationEvent(data);
        return;
    }

    pendingObjectCreationEvents.push({origin, data});

    if (pendingObjectCreationEvents.length > MAX_PENDING_OBJECT_CREATION_EVENTS) {
        pendingObjectCreationEvents.shift();
    }
}

// Listen to "message" type events from web client.
window.addEventListener("message", handlePostMessage, false);

/**
 * Return true if a buffered objectCreation event from the given origin may be delivered, by the same acceptance rule
 * as handlePostMessage, but without switching the trusted origin to "file://": every origin is allowed as long as no
 * trusted origin is set or the trusted origin is "*", and "file://" of the enaio® desktop client is always allowed.
 *
 * @param origin The origin of the event.
 */
function isTrustedOrigin(origin) {
    if (trustedOrigin === null || trustedOrigin === undefined || !(trustedOrigin.length > 0) || trustedOrigin === "*") {
        return true;
    }

    return "file://" === origin || trustedOrigin === origin;
}

/**
 * A function responsible for processing all incoming "messages" from the enaio® webclient.
 *
 * @param event the object passed from the other Window i.e. enaio® webclient.
 * @link https://developer.mozilla.org/en-US/docs/Web/API/Window/postMessage#the_dispatched_event
 */
function handlePostMessage(event) {
    // Todo: Why global?
    webclientOrigin = event.origin;

    /* Ensure "messages" come from a trusted source i.e. your own enaio® hosted domain.
       Ref: https://developer.mozilla.org/en-US/docs/Web/API/Window/postMessage#security_concerns

       "srcOrigin" is the domain URL where enaio® webclient is served. Example: https://enaio.company-name.de
        Please note, in enaio desktop client, "srcOrigin" is represented as "file://" string.
    */
    if (trustedOrigin !== null && trustedOrigin !== undefined && trustedOrigin.length > 0 && trustedOrigin !== "*") {
        // client uses electron webclient so override origin
        if ("file://" === webclientOrigin) {
            trustedOrigin = "file://";
        }

        const safeOrigin = trustedOrigin === webclientOrigin;
		
        if (safeOrigin === false) {
            console.log(`webclientOrigin ${webclientOrigin} is different from srcOrigin ${trustedOrigin}`);
            return false;
        }
    }

    // "handleWebclientMessage" is a handler function which further processes all incoming "messages" from enaio® webclient (see implementation details in the communication-library.js file).
    // Extract the "type" and "data" properties for further processing.
    // Ref: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Destructuring_assignment
    const {type, data} = handleWebclientMessage(event.data);
    delete data?.dapi; // abstraction layer is taking care of it.

    if (type === "onInit") {
		detectDashletModalDialog(data);
        // Do initialization work here.
        onInitCallback(data);
    } else if (type === "onUpdate") {
        // React to osid selection changes here.
        onUpdateCallback(data);
    } else if (type === "objectCreation") {
        // Outcome of an object creation started with createNew.
        handleObjectCreationEvent(data, event.origin);
    }

    return true;
}

/**
 * Detect the kind of script which is running. There are normal dashlets and
 * modal dialogs. They differ in specific way, but we want to make it as smooth
 * to the developer as possible.
 *
 * @param data The init data structure from enaio® webclient.
 */
function detectDashletModalDialog(data) {
	if (data.selectedEntry) {
		modalDialog = true;
		
		if (onUpdateCallbackRegistered) {
			// Unregister onUpdateCallback because it is not available and write a message to console.
			console.error("Modal dialogs do not trigger a update event. Please do not register one.");
			onUpdateCallbackRegistered = false;
			onUpdateCallback = () => {}
		}
	}
}

/**
 * A function that handles "messages" coming from the enaio® webclient.
 *
 * @param payload an object with { type, data } as payload.
 * @returns an object with the same shape as the input payload i.e. { type, data }
 * @link https://help.optimal-systems.com/enaio_develop/display/WEB/5.2+Kommunikation
 */
function handleWebclientMessage(payload) {
    if (payload.msgId && msgQueue[payload.msgId]) {
        clearTimeout(msgQueue[payload.msgId].timer);

        if (payload.data.error !== undefined) {
            msgQueue[payload.msgId].reject(payload.data.error);
        } else if (payload.data.result !== undefined) {
            msgQueue[payload.msgId].resolve(payload.data.result);
        } else {
            msgQueue[payload.msgId].resolve();
        }

        if (alertQueue.includes(payload.msgId)) {
            // display payload info
			alertQueue.splice(alertQueue.indexOf(payload.msgId), 1);
            alert(JSON.stringify(payload.data.result));
        }

        delete msgQueue[payload.msgId];
    }

    return payload;
}

/**
 * Hands the payload over to the enaio® webclient. If a trusted origin is configured, the "message" is
 * restricted to it, otherwise every target origin is allowed.
 *
 * "window" is the Dashlet's JavaScript Window object. Ref: https://developer.mozilla.org/en-US/docs/Web/API/Window
 * "parent" is the enaio® webclient Window object.
 * "postMessage" is the browser API used to communicate between enaio® webclient and the Dashlet. Ref: https://developer.mozilla.org/en-US/docs/Web/API/Window/postMessage
 *
 * @param payload an array with ["method-name", [arguments]] as payload.
 */
function postToParent(payload) {
    if (trustedOrigin !== null && trustedOrigin !== undefined && trustedOrigin.length > 0) {
        window.parent.postMessage(payload, trustedOrigin);
    } else {
        window.parent.postMessage(payload, "*");
    }
}

/**
 * A function responsible for sending "messages" to the enaio® webclient.
 * @param payload an array with ["method-name", [arguments]] as payload. Ref: https://help.optimal-systems.com/enaio_develop/display/WEB/5.4+Dashlet-Methoden
 * @param triggerAlert Boolean. If true, a browser alert (with payload results) will be displayed in the enaio® webclient.
 * @param {{ms: number, error: *}} [timeout] optional. If the webclient does not answer within timeout.ms milliseconds,
 * the promise rejects with timeout.error and a later answer is ignored.
 * @returns a JavaScript Promise. Ref: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Promise
 * @link https://help.optimal-systems.com/enaio_develop/display/WEB/5.2+Kommunikation
 */
async function sendWebclientMessage(payload, triggerAlert = false, timeout = undefined) {
    const msgId = Math.random().toString(36).substr(2, 8);
    payload.push({msgId});

    if (triggerAlert) {
        alertQueue.push(msgId);
    }

    let _resolve, _reject;
    const promise = new Promise((resolve, reject) => {
        _resolve = resolve;
        _reject = reject;
    });

    msgQueue[msgId] = {resolve: _resolve, reject: _reject};

    if (timeout) {
        msgQueue[msgId].timer = setTimeout(() => {
            delete msgQueue[msgId];
            _reject(timeout.error);
        }, timeout.ms);
    }

    try {
        postToParent(payload);
    } catch (error) {
        // Nothing was sent, so neither an answer nor the timeout may follow.
        clearTimeout(msgQueue[msgId]?.timer);
        delete msgQueue[msgId];

        if (alertQueue.includes(msgId)) {
            alertQueue.splice(alertQueue.indexOf(msgId), 1);
        }

        throw error;
    }

    return promise;
}

/**
 * Send a "message" to the enaio® webclient without waiting for an answer.
 *
 * No msgId is attached, so the webclient executes the method but skips the
 * acknowledgment (it only answers when a msgId is present). Used for methods
 * that navigate the current browser tab: depending on where the dashlet is
 * embedded, that navigation destroys the dashlet iframe before the answer
 * can be delivered, so a promise waiting for it could hang forever (DODO-27654).
 */
function sendWebclientMessageFireAndForget(payload) {
    postToParent(payload);
}

/**
 * Return true if we are running inside a modal dialog. If we are running inside a dashlet the return is false.
 */
function isModalDialog() {
	return modalDialog;
}

/**
 * This function is only for the unit-tests to reset the webclient library to its original state
 */
function reset() {
    modalDialog = false;
    onInitCallback = () => {};
    onUpdateCallback = () => {};
    onUpdateCallbackRegistered = false;
    onObjectCreationCallback = undefined;
    pendingObjectCreationEvents.length = 0;
    clearTimeout(objectCreationFlushTimer);
    objectCreationFlushTimer = undefined;

    // Drop the messages waiting with a timeout, so that no timer outlives its test.
    for (const msgId in msgQueue) {
        if (msgQueue[msgId].timer !== undefined) {
            clearTimeout(msgQueue[msgId].timer);
            delete msgQueue[msgId];
        }
    }
}

// Export functions to be used in other JavaScript files.
// Ref: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/import
export {
	registerOnInitCallback, 
	registerOnUpdateCallback,
	registerOnObjectCreationCallback,
	sendWebclientMessage,
	sendWebclientMessageFireAndForget,
	isModalDialog,

    // Only for Unit-Tests
    handlePostMessage,
    reset
};
